
-- [S1] statement 1
-- [S1] The facility set: both GPC plants + Nebraska operating majors with an Unaddressed HPV status today
WITH f AS (SELECT PGM_SYS_ID, ANY_VALUE(REGISTRY_ID) AS REG, ANY_VALUE(FACILITY_NAME) AS NM, ANY_VALUE(CITY) AS CITY, ANY_VALUE(COUNTY_NAME) AS CNTY, ANY_VALUE(STATE) AS ST,
  ANY_VALUE(NAICS_CODES) AS NAICS, ANY_VALUE(AIR_POLLUTANT_CLASS_CODE) AS CLS, ANY_VALUE(AIR_OPERATING_STATUS_CODE) AS OP, ANY_VALUE(CURRENT_HPV) AS HPV
  FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FACILITIES GROUP BY 1)
SELECT IFF(ST='NE','NE15','GPC') AS GRP, * FROM f
WHERE (ST='NE' AND CLS='MAJ' AND OP='OPR' AND HPV ILIKE 'Unaddressed%')
   OR (UPPER(NM) LIKE '%GRAIN PROCESSING%' AND ST IN ('IA','IN'))
ORDER BY 1, ST, NM;

-- [S2] statement 2
-- [S2] FRS program links for the 18 registry IDs: which other EPA / federal systems each plant sits in
SELECT TO_VARCHAR(REGISTRY_ID) AS REG, PGM_SYS_ACRNM, COUNT(*) AS N, LISTAGG(DISTINCT PGM_SYS_ID, ';') WITHIN GROUP (ORDER BY PGM_SYS_ID) AS IDS, ANY_VALUE(PRIMARY_NAME) AS NM, ANY_VALUE(CITY_NAME) AS CITY, ANY_VALUE(FIPS_CODE) AS FIPS
FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_FRS_FRS_PROGRAM_LINKS
WHERE TO_VARCHAR(REGISTRY_ID) IN ('110017404548','110005972821','110041204265','110020497121','110000448043','110000448472','110000596793','110030484107','110022409883','110037424533','110000606504','110031127126','110040499449','110070005201','110030917603','110029535171','110000615503','110001505602')
GROUP BY 1,2 ORDER BY 1,2;

-- [S3] statement 3
-- [S3] Air emissions (EIS, TRI, GHGRP, CAMD combined) for the 18 registry IDs, by registry, program, year, pollutant
SELECT TO_VARCHAR(REGISTRY_ID) AS REG, PGM_SYS_ACRNM, REPORTING_YEAR, POLLUTANT_NAME, UNIT_OF_MEASURE, SUM(ANNUAL_EMISSION) AS EM, COUNT(*) AS N
FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_AIR_EMISSIONS_POLL_RPT_COMBINED_EMISSIONS
WHERE TO_VARCHAR(REGISTRY_ID) IN ('110017404548','110005972821','110041204265','110020497121','110000448043','110000448472','110000596793','110030484107','110022409883','110037424533','110000606504','110031127126','110040499449','110070005201','110030917603','110029535171','110000615503','110001505602')
GROUP BY 1,2,3,4,5 ORDER BY 1,2,3,4;

-- [S4] statement 4
-- [S4] Parent company as each program records it: GHGRP facility (by FRS_ID) and TRI facility (by FRS_ID / EPA_REGISTRY_ID)
SELECT 'GHGRP' AS SRC, TO_VARCHAR(FRS_ID) AS REG, FACILITY_NAME AS NM, CITY, STATE AS ST, PARENT_COMPANY AS PARENT, MIN(REPORTING_YEAR)::VARCHAR AS Y0, MAX(REPORTING_YEAR)::VARCHAR AS Y1, COUNT(*) AS N
FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_GHGRP_FACILITY WHERE TO_VARCHAR(FRS_ID) IN ('110017404548','110005972821','110041204265','110020497121','110000448043','110000448472','110000596793','110030484107','110022409883','110037424533','110000606504','110031127126','110040499449','110070005201','110030917603','110029535171','110000615503','110001505602') GROUP BY 1,2,3,4,5,6
UNION ALL
SELECT 'TRI', COALESCE(TO_VARCHAR(FRS_ID), TO_VARCHAR(EPA_REGISTRY_ID)), FACILITY_NAME, CITY_NAME, STATE_ABBR, COALESCE(STANDARDIZED_PARENT_COMPANY, PARENT_CO_NAME) || ' / DB ' || COALESCE(PARENT_CO_DB_NUM,'-'), TRI_FACILITY_ID, FAC_CLOSED_IND, COUNT(*)
FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_TRI_FACILITY WHERE TO_VARCHAR(FRS_ID) IN ('110017404548','110005972821','110041204265','110020497121','110000448043','110000448472','110000596793','110030484107','110022409883','110037424533','110000606504','110031127126','110040499449','110070005201','110030917603','110029535171','110000615503','110001505602') OR TO_VARCHAR(EPA_REGISTRY_ID) IN ('110017404548','110005972821','110041204265','110020497121','110000448043','110000448472','110000596793','110030484107','110022409883','110037424533','110000606504','110031127126','110040499449','110070005201','110030917603','110029535171','110000615503','110001505602') GROUP BY 1,2,3,4,5,6,7,8
ORDER BY 2,1;

-- [S5] statement 5
-- [S5] Chart rows: GPC Muscatine IA vs GPC Washington IN, per year 2005-2026: stack-test fail days, all test days, formal actions (state/EPA) and penalty $, informal actions
WITH g AS (SELECT * FROM (VALUES ('IA0000001913900025','Muscatine IA'),('IN0000001802700046','Washington IN')) v(PGM_SYS_ID, PLANT)),
st AS (SELECT PGM_SYS_ID, YEAR(ACTUAL_END_DATE) AS YR, COUNT(DISTINCT IFF(AIR_STACK_TEST_STATUS_CODE='FAI', ACTUAL_END_DATE, NULL)) AS FAIL_DAYS, COUNT(DISTINCT ACTUAL_END_DATE) AS TEST_DAYS, COUNT_IF(AIR_STACK_TEST_STATUS_CODE='FAI') AS FAIL_ROWS
  FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_STACK_TESTS WHERE PGM_SYS_ID IN (SELECT PGM_SYS_ID FROM g) GROUP BY 1,2),
fa AS (SELECT PGM_SYS_ID, YEAR(SETTLEMENT_ENTERED_DATE) AS YR, COUNT(*) AS FORMAL, COUNT_IF(STATE_EPA_FLAG='S') AS FORMAL_STATE, COUNT_IF(STATE_EPA_FLAG='E') AS FORMAL_EPA, SUM(COALESCE(PENALTY_AMOUNT,0)) AS PENALTY, LISTAGG(DISTINCT ENF_TYPE_DESC, ';') AS FA_TYPES
  FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FORMAL_ACTIONS WHERE PGM_SYS_ID IN (SELECT PGM_SYS_ID FROM g) GROUP BY 1,2),
ia AS (SELECT PGM_SYS_ID, YEAR(ACHIEVED_DATE) AS YR, COUNT(*) AS INFORMAL, LISTAGG(DISTINCT ENF_TYPE_DESC, ';') AS IA_TYPES
  FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_INFORMAL_ACTIONS WHERE PGM_SYS_ID IN (SELECT PGM_SYS_ID FROM g) GROUP BY 1,2),
vh AS (SELECT PGM_SYS_ID, YEAR(COALESCE(HPV_DAYZERO_DATE, EARLIEST_FRV_DETERM_DATE)) AS YR, COUNT(*) AS VIOL, COUNT(HPV_DAYZERO_DATE) AS HPV
  FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_VIOLATION_HISTORY WHERE PGM_SYS_ID IN (SELECT PGM_SYS_ID FROM g) GROUP BY 1,2),
k AS (SELECT PGM_SYS_ID, YR FROM st UNION SELECT PGM_SYS_ID, YR FROM fa UNION SELECT PGM_SYS_ID, YR FROM ia UNION SELECT PGM_SYS_ID, YR FROM vh)
SELECT g.PLANT, k.YR, st.TEST_DAYS, st.FAIL_DAYS, st.FAIL_ROWS, vh.VIOL, vh.HPV, ia.INFORMAL, fa.FORMAL, fa.FORMAL_STATE, fa.FORMAL_EPA, fa.PENALTY, fa.FA_TYPES, ia.IA_TYPES
FROM k JOIN g USING (PGM_SYS_ID) LEFT JOIN st USING (PGM_SYS_ID, YR) LEFT JOIN fa USING (PGM_SYS_ID, YR) LEFT JOIN ia USING (PGM_SYS_ID, YR) LEFT JOIN vh USING (PGM_SYS_ID, YR)
ORDER BY 1,2;

-- [S6] statement 6
-- [S6] ECHO facility rows for the 18 registry IDs: neighbourhood (PCT_MINORITY, density, county FIPS), programs, compliance history, counts
SELECT TO_VARCHAR(FRS_ID) AS REG, FACILITY_NAME, CITY, STATE, COUNTY, FIPS_CODE, PCT_MINORITY, POPULATION_DENSITY, HAS_AIR_PROGRAM AS AIR, HAS_WATER_PROGRAM AS WAT, HAS_HAZWASTE_PROGRAM AS RCRA, HAS_TOXIC_RELEASE_PROGRAM AS TRI, HAS_GREENHOUSE_GAS_PROGRAM AS GHG,
  COMPLIANCE_STATUS, QUARTERS_WITH_NONCOMPLIANCE AS QNC, THREE_YR_COMPLIANCE_HISTORY AS HIST, TOTAL_INSPECTION_COUNT AS INSP, DATE_LAST_INSPECTION, INFORMAL_ACTION_COUNT AS INF, FORMAL_ACTION_COUNT AS FORMAL, DATE_LAST_FORMAL_ACTION, LAST_PENALTY_AMT_ALLOCATED, DATE_LAST_PENALTY, TRI_ON_SITE_RELEASES, IS_MAJOR_FACILITY, IS_ACTIVE
FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ECHO
WHERE TO_VARCHAR(FRS_ID) IN ('110017404548','110005972821','110041204265','110020497121','110000448043','110000448472','110000596793','110030484107','110022409883','110037424533','110000606504','110031127126','110040499449','110070005201','110030917603','110029535171','110000615503','110001505602') ORDER BY STATE, FACILITY_NAME;

-- [S7] statement 7
-- [S7] Water (NPDES) enforcement for every NPDES permit FRS links to the 18 plants: formal actions (all dates) and informal actions since 2015, plus quarters in noncompliance since 2015
WITH ids AS (SELECT column1 AS NPDES_ID FROM VALUES ('IA0003441'),('IN0059641'),('INR10H048'),('INRA02726'),('INRA03535'),('INRA11911'),('INRM00667'),('NE0000787'),('NE0130141'),('NE0131539'),('NE0131679'),('NE0133850'),('NE0134261'),('NE0137707'),('NE0137715'),('NE0137804'),('NE0137839'),('NER000338'),('NEU001115')),
fa AS (SELECT NPDES_ID, COUNT(*) AS FORMAL_ALL, COUNT_IF(SETTLEMENT_ENTERED_DATE >= '2015-01-01') AS FORMAL_15, SUM(COALESCE(FED_PENALTY_ASSESSED_AMT,0)+COALESCE(STATE_LOCAL_PENALTY_AMT,0)) AS PEN_ALL,
   LISTAGG(AGENCY || ':' || COALESCE(TO_VARCHAR(SETTLEMENT_ENTERED_DATE),'nodate') || ':' || ENF_TYPE_DESC || ':$' || TO_VARCHAR(COALESCE(FED_PENALTY_ASSESSED_AMT,0)+COALESCE(STATE_LOCAL_PENALTY_AMT,0)), ' | ') WITHIN GROUP (ORDER BY SETTLEMENT_ENTERED_DATE) AS FA_LIST
   FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_NPDES_NPDES_FORMAL_ENFORCEMENT_ACTIONS WHERE NPDES_ID IN (SELECT NPDES_ID FROM ids) GROUP BY 1),
ia AS (SELECT NPDES_ID, COUNT(*) AS INF_15, LISTAGG(DISTINCT ENF_TYPE_DESC, ';') AS INF_TYPES FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_NPDES_NPDES_INFORMAL_ENFORCEMENT_ACTIONS WHERE ACHIEVED_DATE >= '2015-01-01' AND NPDES_ID IN (SELECT NPDES_ID FROM ids) GROUP BY 1),
q AS (SELECT NPDES_ID, COUNT(*) AS QTRS, COUNT_IF(HLRNC IS NOT NULL AND HLRNC NOT IN ('','C','0')) AS QTRS_NONCOMP, LISTAGG(DISTINCT HLRNC, ',') AS HLRNC_VALS, SUM(TRY_TO_NUMBER(NUME90_Q)) AS EFFLUENT_EXCEED
   FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_NPDES_NPDES_QNCR_HISTORY WHERE NPDES_ID IN (SELECT NPDES_ID FROM ids) AND LEFT(YEARQTR,4) >= '2015' GROUP BY 1)
SELECT ids.NPDES_ID, fa.FORMAL_ALL, fa.FORMAL_15, fa.PEN_ALL, ia.INF_15, ia.INF_TYPES, q.QTRS, q.QTRS_NONCOMP, q.HLRNC_VALS, q.EFFLUENT_EXCEED, fa.FA_LIST
FROM ids LEFT JOIN fa USING (NPDES_ID) LEFT JOIN ia USING (NPDES_ID) LEFT JOIN q USING (NPDES_ID) ORDER BY 1;

-- [S8] statement 8
-- [S8] Hazardous waste (RCRA) enforcement and violations for the linked handler IDs, plus EPA federal enforcement cases (ICIS FE&C) by registry ID
SELECT 'RCRA_ENF' AS SRC, ID_NUMBER AS ID, TO_VARCHAR(ENFORCEMENT_ACTION_DATE) AS D, ENFORCEMENT_AGENCY AS AG, ENFORCEMENT_TYPE || ' ' || ENFORCEMENT_DESC AS WHAT, TO_VARCHAR(COALESCE(TRY_TO_NUMBER(TO_VARCHAR(PMP_AMOUNT)),0)+COALESCE(TRY_TO_NUMBER(TO_VARCHAR(FMP_AMOUNT)),0)) AS AMT
FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_RCRA_ENFORCEMENTS WHERE ID_NUMBER IN ('IAD000610493','IAD005269923','INR000021105','NED007260672','NED047042270','NED986387942','NER000000471','NER000500207','NER000504902','NER000505917','NER000506741','NER000511972','NER000514638')
UNION ALL
SELECT 'RCRA_VIOL', ID_NUMBER, TO_VARCHAR(DATE_VIOLATION_DETERMINED), VIOL_DETERMINED_BY_AGENCY, VIOLATION_TYPE || ' ' || VIOLATION_TYPE_DESC, TO_VARCHAR(ACTUAL_RTC_DATE)
FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_RCRA_VIOLATIONS WHERE ID_NUMBER IN ('IAD000610493','IAD005269923','INR000021105','NED007260672','NED047042270','NED986387942','NER000000471','NER000500207','NER000504902','NER000505917','NER000506741','NER000511972','NER000514638')
UNION ALL
SELECT 'FEC_CASE', TO_VARCHAR(REGISTRY_ID), CASE_NUMBER, ACTIVITY_ID::VARCHAR, FACILITY_NAME || ' / ' || CITY, PRIMARY_NAICS_CODE
FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_EPA_ICIS_FEC_CASE_FACILITIES WHERE TO_VARCHAR(REGISTRY_ID) IN ('110017404548','110005972821','110041204265','110020497121','110000448043','110000448472','110000596793','110030484107','110022409883','110037424533','110000606504','110031127126','110040499449','110070005201','110030917603','110029535171','110000615503','110001505602')
UNION ALL
SELECT 'FEC_EPA_INF', TO_VARCHAR(REGISTRY_ID), TO_VARCHAR(ACHIEVED_DATE), PGM_SYS_ACRNM || ' ' || AGENCY, ENF_TYPE_DESC, STATUTE
FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_EPA_ICIS_FEC_EPA_INFORMAL_ENFORCEMENT_ACTIONS WHERE TO_VARCHAR(REGISTRY_ID) IN ('110017404548','110005972821','110041204265','110020497121','110000448043','110000448472','110000596793','110030484107','110022409883','110037424533','110000606504','110031127126','110040499449','110070005201','110030917603','110029535171','110000615503','110001505602')
ORDER BY 1,2,3;

-- [S9] statement 9
-- [S9] OSHA: enforcement inspections and ITA 300A injury summaries for Grain Processing Corp, name + city + state (second field: city must be Muscatine or Washington)
SELECT 'INSP' AS SRC, SITE_STATE AS ST, SITE_CITY AS CITY, ESTAB_NAME AS NM, SITE_ADDRESS AS ADDR, TO_VARCHAR(OPEN_DATE) AS D, INSP_TYPE || '/' || INSP_SCOPE || '/' || SAFETY_HLTH AS WHAT, NR_IN_ESTAB::VARCHAR AS N_EMP, NULL AS INJ, NULL AS HOURS
FROM LIBRARY_MARTS.ECONOMICS.ECONOMICS__FED_DOL_OSHA_INSPECTIONS
WHERE (UPPER(ESTAB_NAME) LIKE '%GRAIN PROCESSING%' OR UPPER(ESTAB_NAME) LIKE 'GPC%' OR UPPER(ESTAB_NAME) LIKE '%KENT CORP%') AND SITE_STATE IN ('IA','IN')
UNION ALL
SELECT 'ITA_' || YEAR_FILING_FOR::VARCHAR, STATE, CITY, ESTABLISHMENT_NAME || ' / ' || COALESCE(COMPANY_NAME,''), STREET_ADDRESS, EIN, ANNUAL_AVERAGE_EMPLOYEES::VARCHAR, TOTAL_HOURS_WORKED::VARCHAR, TOTAL_DAFW_CASES::VARCHAR || ' DAFW, ' || TOTAL_DJTR_CASES::VARCHAR || ' DJTR, ' || TOTAL_OTHER_CASES::VARCHAR || ' other, ' || TOTAL_DEATHS::VARCHAR || ' deaths, resp ' || TOTAL_RESPIRATORY_CONDITIONS::VARCHAR, NAICS_CODE::VARCHAR
FROM (SELECT * FROM LIBRARY_MARTS.LABOR.LABOR__FED_OSHA_ITA_300A_SUMMARY_2023 UNION ALL SELECT * FROM LIBRARY_MARTS.LABOR.LABOR__FED_OSHA_ITA_300A_SUMMARY_2024 UNION ALL SELECT * FROM LIBRARY_MARTS.LABOR.LABOR__FED_OSHA_ITA_300A_SUMMARY_2025)
WHERE (UPPER(ESTABLISHMENT_NAME) LIKE '%GRAIN PROCESSING%' OR UPPER(COMPANY_NAME) LIKE '%GRAIN PROCESSING%' OR UPPER(COMPANY_NAME) LIKE '%KENT CORP%') AND STATE IN ('IA','IN')
ORDER BY 1,2,6;

-- [S10] statement 10
-- [S10] Federal contracts (USAspending R2, uncapped) to Grain Processing Corp or Kent Corp / Kent Nutrition, by recipient + parent name; grouped by recipient, state, agency, fiscal year of action
SELECT RECIPIENT_NAME, RECIPIENT_PARENT_NAME, RECIPIENT_UEI, RECIPIENT_CITY_NAME, RECIPIENT_STATE_CODE, AWARDING_SUB_AGENCY_NAME, YEAR(ACTION_DATE) AS YR,
  COUNT(*) AS N_ACTIONS, COUNT(DISTINCT CONTRACT_AWARD_UNIQUE_KEY) AS N_AWARDS, SUM(FEDERAL_ACTION_OBLIGATION) AS OBLIG, MIN(ACTION_DATE) AS FIRST_ACT, ANY_VALUE(PRODUCT_OR_SERVICE_CODE_DESCRIPTION) AS PSC
FROM LIBRARY_MARTS.ECONOMICS.ECONOMICS__FED_USASPENDING_CONTRACTS_FULL_R2
WHERE UPPER(RECIPIENT_NAME) LIKE '%GRAIN PROCESSING%' OR UPPER(RECIPIENT_PARENT_NAME) LIKE '%GRAIN PROCESSING%'
   OR UPPER(RECIPIENT_NAME) LIKE 'KENT CORP%' OR UPPER(RECIPIENT_PARENT_NAME) LIKE 'KENT CORP%' OR UPPER(RECIPIENT_NAME) LIKE 'KENT NUTRITION%'
GROUP BY 1,2,3,4,5,6,7 ORDER BY 1,7;

-- [S10] statement 11
-- [S10] Federal contracts (USAspending R2, uncapped) to Grain Processing Corp or Kent Corp / Kent Nutrition, by recipient + parent name; grouped by recipient, state, agency, fiscal year of action
SELECT RECIPIENT_NAME, RECIPIENT_PARENT_NAME, RECIPIENT_UEI, RECIPIENT_CITY_NAME, RECIPIENT_STATE_CODE, AWARDING_SUB_AGENCY_NAME, LEFT(ACTION_DATE,4) AS YR,
  COUNT(*) AS N_ACTIONS, COUNT(DISTINCT CONTRACT_AWARD_UNIQUE_KEY) AS N_AWARDS, SUM(FEDERAL_ACTION_OBLIGATION) AS OBLIG, MIN(ACTION_DATE) AS FIRST_ACT, ANY_VALUE(PRODUCT_OR_SERVICE_CODE_DESCRIPTION) AS PSC
FROM LIBRARY_MARTS.ECONOMICS.ECONOMICS__FED_USASPENDING_CONTRACTS_FULL_R2
WHERE UPPER(RECIPIENT_NAME) LIKE '%GRAIN PROCESSING%' OR UPPER(RECIPIENT_PARENT_NAME) LIKE '%GRAIN PROCESSING%'
   OR UPPER(RECIPIENT_NAME) LIKE 'KENT CORP%' OR UPPER(RECIPIENT_PARENT_NAME) LIKE 'KENT CORP%' OR UPPER(RECIPIENT_NAME) LIKE 'KENT NUTRITION%'
GROUP BY 1,2,3,4,5,6,7 ORDER BY 1,7;

-- [S11] statement 12
-- [S11] Federal assistance (grants, loans, subsidies; USAspending ASSISTANCE_FULL, 128M rows) to Grain Processing Corp or Kent Corp, by name, grouped
SELECT RECIPIENT_NAME, RECIPIENT_PARENT_NAME, RECIPIENT_UEI, RECIPIENT_CITY_NAME, RECIPIENT_STATE_CODE, AWARDING_SUB_AGENCY_NAME, CFDA_NUMBER, CFDA_TITLE, ASSISTANCE_TYPE_DESCRIPTION,
  COUNT(*) AS N_ACTIONS, COUNT(DISTINCT ASSISTANCE_AWARD_UNIQUE_KEY) AS N_AWARDS, SUM(FEDERAL_ACTION_OBLIGATION) AS OBLIG, SUM(FACE_VALUE_OF_LOAN) AS LOAN_FACE, MIN(ACTION_DATE) AS FIRST_ACT, MAX(ACTION_DATE) AS LAST_ACT
FROM LIBRARY_MARTS.ECONOMICS.ECONOMICS__FED_USASPENDING_ASSISTANCE_FULL
WHERE UPPER(RECIPIENT_NAME) LIKE '%GRAIN PROCESSING%' OR UPPER(RECIPIENT_PARENT_NAME) LIKE '%GRAIN PROCESSING%'
   OR UPPER(RECIPIENT_NAME) LIKE 'KENT CORP%' OR UPPER(RECIPIENT_PARENT_NAME) LIKE 'KENT CORP%' OR UPPER(RECIPIENT_NAME) LIKE 'KENT NUTRITION%'
GROUP BY 1,2,3,4,5,6,7,8,9 ORDER BY 1,14;

-- [S12] statement 13
-- [S12] GPC Biofuel Producer Program awards, one row per transaction: award key, dates, amount, place of performance, description
SELECT ASSISTANCE_AWARD_UNIQUE_KEY, AWARD_ID_FAIN, MODIFICATION_NUMBER, ACTION_DATE, FEDERAL_ACTION_OBLIGATION, TOTAL_OBLIGATED_AMOUNT, RECIPIENT_ADDRESS_LINE_1, PRIMARY_PLACE_OF_PERFORMANCE_CITY_NAME AS POP_CITY, PRIMARY_PLACE_OF_PERFORMANCE_STATE_NAME AS POP_ST, PERIOD_OF_PERFORMANCE_START_DATE, TRANSACTION_DESCRIPTION
FROM LIBRARY_MARTS.ECONOMICS.ECONOMICS__FED_USASPENDING_ASSISTANCE_FULL
WHERE RECIPIENT_UEI = 'TAR2QK955KK4' OR RECIPIENT_PARENT_UEI = 'TAR2QK955KK4'
ORDER BY ACTION_DATE;

-- [S13] statement 14
-- [S13] USDA Biofuel Producer Program (CFDA 10.378) grants to Nebraska recipients, and to Iowa/Indiana GPC for reference: by recipient, UEI, city
SELECT RECIPIENT_STATE_CODE AS ST, RECIPIENT_NAME, RECIPIENT_PARENT_NAME, RECIPIENT_UEI, RECIPIENT_CITY_NAME, RECIPIENT_ADDRESS_LINE_1,
  COUNT(DISTINCT ASSISTANCE_AWARD_UNIQUE_KEY) AS N_AWARDS, SUM(FEDERAL_ACTION_OBLIGATION) AS OBLIG, MIN(ACTION_DATE) AS FIRST_ACT
FROM LIBRARY_MARTS.ECONOMICS.ECONOMICS__FED_USASPENDING_ASSISTANCE_FULL
WHERE CFDA_NUMBER = '10.378' AND (RECIPIENT_STATE_CODE = 'NE' OR RECIPIENT_UEI = 'TAR2QK955KK4')
GROUP BY 1,2,3,4,5,6 ORDER BY OBLIG DESC;

-- [S14] statement 15
-- [S14] The 15 Nebraska unaddressed majors: open HPVs (day zero, pollutants, agency), plus ICIS-Air formal actions since 2015 and informal actions since 2015, and stack-test fails since 2015
WITH f AS (SELECT PGM_SYS_ID, ANY_VALUE(FACILITY_NAME) AS NM, ANY_VALUE(CITY) AS CITY FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FACILITIES
  WHERE STATE='NE' GROUP BY 1 HAVING ANY_VALUE(AIR_POLLUTANT_CLASS_CODE)='MAJ' AND ANY_VALUE(AIR_OPERATING_STATUS_CODE)='OPR' AND ANY_VALUE(CURRENT_HPV) ILIKE 'Unaddressed%'),
v AS (SELECT PGM_SYS_ID, COUNT_IF(HPV_DAYZERO_DATE IS NOT NULL AND HPV_RESOLVED_DATE IS NULL) AS OPEN_HPV, MIN(IFF(HPV_RESOLVED_DATE IS NULL, HPV_DAYZERO_DATE, NULL)) AS OLDEST_OPEN, MAX(IFF(HPV_RESOLVED_DATE IS NULL, HPV_DAYZERO_DATE, NULL)) AS NEWEST_OPEN,
   LISTAGG(DISTINCT IFF(HPV_RESOLVED_DATE IS NULL AND HPV_DAYZERO_DATE IS NOT NULL, POLLUTANT_CODES, NULL), ';') AS OPEN_POLS, LISTAGG(DISTINCT IFF(HPV_RESOLVED_DATE IS NULL AND HPV_DAYZERO_DATE IS NOT NULL, AGENCY_TYPE_DESC, NULL), ';') AS OPEN_AGENCY,
   COUNT_IF(COALESCE(HPV_DAYZERO_DATE, EARLIEST_FRV_DETERM_DATE) >= '2015-01-01') AS VIOL_15
   FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_VIOLATION_HISTORY WHERE PGM_SYS_ID IN (SELECT PGM_SYS_ID FROM f) GROUP BY 1),
fa AS (SELECT PGM_SYS_ID, COUNT(*) AS FORMAL_15, LISTAGG(STATE_EPA_FLAG || ':' || TO_VARCHAR(SETTLEMENT_ENTERED_DATE), ';') AS FA_LIST FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FORMAL_ACTIONS WHERE SETTLEMENT_ENTERED_DATE >= '2015-01-01' AND PGM_SYS_ID IN (SELECT PGM_SYS_ID FROM f) GROUP BY 1),
ia AS (SELECT PGM_SYS_ID, COUNT(*) AS INF_15 FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_INFORMAL_ACTIONS WHERE ACHIEVED_DATE >= '2015-01-01' AND PGM_SYS_ID IN (SELECT PGM_SYS_ID FROM f) GROUP BY 1),
st AS (SELECT PGM_SYS_ID, COUNT(DISTINCT IFF(AIR_STACK_TEST_STATUS_CODE='FAI', ACTUAL_END_DATE, NULL)) AS FAIL_DAYS_15 FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_STACK_TESTS WHERE ACTUAL_END_DATE >= '2015-01-01' AND PGM_SYS_ID IN (SELECT PGM_SYS_ID FROM f) GROUP BY 1)
SELECT f.NM, f.CITY, v.OPEN_HPV, v.OLDEST_OPEN, v.NEWEST_OPEN, v.OPEN_POLS, v.OPEN_AGENCY, v.VIOL_15, COALESCE(fa.FORMAL_15,0) AS FORMAL_15, fa.FA_LIST, COALESCE(ia.INF_15,0) AS INF_15, COALESCE(st.FAIL_DAYS_15,0) AS FAIL_DAYS_15
FROM f LEFT JOIN v USING (PGM_SYS_ID) LEFT JOIN fa USING (PGM_SYS_ID) LEFT JOIN ia USING (PGM_SYS_ID) LEFT JOIN st USING (PGM_SYS_ID) ORDER BY v.OLDEST_OPEN;

-- [S15] statement 16
-- [S15] Decode the pollutant codes on open NE HPVs and GPC fails (ICIS-Air pollutant table), plus GPC pre-2017 fail pollutant codes
SELECT POLLUTANT_CODE, ANY_VALUE(POLLUTANT_DESC) AS DESCR, COUNT(*) AS N
FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_POLLUTANTS
WHERE POLLUTANT_CODE IN ('300000282','300000327','300000243','300000377','10461','300000119','300000007','300000088','300000329','300000330','300000331','300000268')
GROUP BY 1 ORDER BY 1;

-- [S16] statement 17
-- [S16] Peer group: every operating major air source with NAICS 311221 (wet corn milling) nationally: stack-test fail days, violations, HPVs, informal and formal actions and penalties, 2015-2025
WITH f AS (SELECT PGM_SYS_ID, ANY_VALUE(FACILITY_NAME) AS NM, ANY_VALUE(CITY) AS CITY, ANY_VALUE(STATE) AS ST FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FACILITIES
  GROUP BY 1 HAVING ANY_VALUE(AIR_POLLUTANT_CLASS_CODE)='MAJ' AND ANY_VALUE(AIR_OPERATING_STATUS_CODE)='OPR' AND ANY_VALUE(NAICS_CODES) LIKE '%311221%'),
st AS (SELECT PGM_SYS_ID, COUNT(DISTINCT ACTUAL_END_DATE) AS TEST_DAYS, COUNT(DISTINCT IFF(AIR_STACK_TEST_STATUS_CODE='FAI', ACTUAL_END_DATE, NULL)) AS FAIL_DAYS FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_STACK_TESTS
  WHERE ACTUAL_END_DATE >= '2015-01-01' AND ACTUAL_END_DATE < '2026-01-01' AND PGM_SYS_ID IN (SELECT PGM_SYS_ID FROM f) GROUP BY 1),
v AS (SELECT PGM_SYS_ID, COUNT(*) AS VIOL, COUNT(HPV_DAYZERO_DATE) AS HPV FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_VIOLATION_HISTORY
  WHERE COALESCE(HPV_DAYZERO_DATE, EARLIEST_FRV_DETERM_DATE) >= '2015-01-01' AND COALESCE(HPV_DAYZERO_DATE, EARLIEST_FRV_DETERM_DATE) < '2026-01-01' AND PGM_SYS_ID IN (SELECT PGM_SYS_ID FROM f) GROUP BY 1),
ia AS (SELECT PGM_SYS_ID, COUNT(*) AS INF FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_INFORMAL_ACTIONS WHERE ACHIEVED_DATE >= '2015-01-01' AND ACHIEVED_DATE < '2026-01-01' AND PGM_SYS_ID IN (SELECT PGM_SYS_ID FROM f) GROUP BY 1),
fa AS (SELECT PGM_SYS_ID, COUNT(*) AS FORMAL, SUM(COALESCE(PENALTY_AMOUNT,0)) AS PEN FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FORMAL_ACTIONS WHERE SETTLEMENT_ENTERED_DATE >= '2015-01-01' AND SETTLEMENT_ENTERED_DATE < '2026-01-01' AND PGM_SYS_ID IN (SELECT PGM_SYS_ID FROM f) GROUP BY 1)
SELECT f.NM, f.CITY, f.ST, COALESCE(TEST_DAYS,0) AS TEST_DAYS, COALESCE(FAIL_DAYS,0) AS FAIL_DAYS, COALESCE(VIOL,0) AS VIOL, COALESCE(HPV,0) AS HPV, COALESCE(INF,0) AS INF, COALESCE(FORMAL,0) AS FORMAL, COALESCE(PEN,0) AS PEN
FROM f LEFT JOIN st USING (PGM_SYS_ID) LEFT JOIN v USING (PGM_SYS_ID) LEFT JOIN ia USING (PGM_SYS_ID) LEFT JOIN fa USING (PGM_SYS_ID)
ORDER BY FAIL_DAYS DESC, VIOL DESC;

-- [S17] statement 18
-- [S17] TRI 2023 peer group: every facility with primary NAICS 311221 (wet corn milling): air releases (fugitive + stack, lb), acetaldehyde air, carcinogen air, rank
SELECT C_3_FRS_ID AS REG, C_4_FACILITY_NAME AS NM, C_6_CITY AS CITY, C_8_ST AS ST, C_17_STANDARD_PARENT_CO_NAME AS PARENT,
  SUM(COALESCE(TRY_TO_NUMBER(TO_VARCHAR(C_51_5_1_FUGITIVE_AIR),38,4),0) + COALESCE(TRY_TO_NUMBER(TO_VARCHAR(C_52_5_2_STACK_AIR),38,4),0)) AS AIR_LB,
  SUM(IFF(UPPER(C_37_CHEMICAL)='ACETALDEHYDE', COALESCE(TRY_TO_NUMBER(TO_VARCHAR(C_51_5_1_FUGITIVE_AIR),38,4),0) + COALESCE(TRY_TO_NUMBER(TO_VARCHAR(C_52_5_2_STACK_AIR),38,4),0), 0)) AS ACETALD_LB,
  SUM(IFF(UPPER(C_46_CARCINOGEN) IN ('YES','Y','TRUE'), COALESCE(TRY_TO_NUMBER(TO_VARCHAR(C_51_5_1_FUGITIVE_AIR),38,4),0) + COALESCE(TRY_TO_NUMBER(TO_VARCHAR(C_52_5_2_STACK_AIR),38,4),0), 0)) AS CARCIN_AIR_LB,
  COUNT(*) AS N_CHEM, MAX(C_50_UNIT_OF_MEASURE) AS UNIT_MAX, MIN(C_50_UNIT_OF_MEASURE) AS UNIT_MIN
FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_TRI_BASIC_2023
WHERE TO_VARCHAR(C_30_PRIMARY_NAICS) LIKE '311221%'
GROUP BY 1,2,3,4,5 ORDER BY AIR_LB DESC;

-- [S18] statement 19
-- [S18] Why no EIS (National Emissions Inventory) rows for GPC Muscatine? Look for any EIS or other registry record in Muscatine IA under a GPC-like name
SELECT TO_VARCHAR(REGISTRY_ID) AS REG, PGM_SYS_ACRNM, PGM_SYS_ID, PRIMARY_NAME, LOCATION_ADDRESS, CITY_NAME, STATE_CODE
FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_FRS_FRS_PROGRAM_LINKS
WHERE STATE_CODE = 'IA' AND UPPER(CITY_NAME) = 'MUSCATINE' AND (UPPER(PRIMARY_NAME) LIKE '%GRAIN PROC%' OR UPPER(PRIMARY_NAME) LIKE 'GPC%' OR UPPER(PRIMARY_NAME) LIKE '%KENT%' OR UPPER(LOCATION_ADDRESS) LIKE '1600 OREGON%')
ORDER BY 1,2;

-- [S19] statement 20
-- [S19] National Emissions Inventory (EIS) for GPC Muscatine, which sits on a second registry ID (110072214456), vs GPC Washington IN (110041204265): criteria pollutants by inventory year, pounds
SELECT TO_VARCHAR(REGISTRY_ID) AS REG, REPORTING_YEAR, POLLUTANT_NAME, SUM(ANNUAL_EMISSION) AS LB, COUNT(*) AS N
FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_AIR_EMISSIONS_POLL_RPT_COMBINED_EMISSIONS
WHERE TO_VARCHAR(REGISTRY_ID) IN ('110072214456','110041204265') AND PGM_SYS_ACRNM = 'EIS'
  AND POLLUTANT_NAME IN ('Sulfur dioxide','Nitrogen oxides','Volatile organic compounds','Primary PM2.5 (filterables and condensibles)','Primary PM10 (filterables and condensibles)','Carbon monoxide','Lead','Acetaldehyde','Hydrochloric acid','Mercury')
GROUP BY 1,2,3 ORDER BY 3,1,2;

-- [S20] statement 21
-- [S20] Peer trend: TRI air pounds per year for operating major ethanol plants (NAICS 325193) nationally, split: the NE unaddressed ethanol plants, other Nebraska, Iowa, all other states. Join ICIS-Air facilities to combined emissions on REGISTRY_ID
WITH f AS (SELECT TO_VARCHAR(ANY_VALUE(REGISTRY_ID)) AS REG, ANY_VALUE(STATE) AS ST, ANY_VALUE(CURRENT_HPV) AS HPV FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FACILITIES
  GROUP BY PGM_SYS_ID HAVING ANY_VALUE(AIR_POLLUTANT_CLASS_CODE)='MAJ' AND ANY_VALUE(AIR_OPERATING_STATUS_CODE)='OPR' AND ANY_VALUE(NAICS_CODES) LIKE '%325193%'),
g AS (SELECT REG, MAX(CASE WHEN ST='NE' AND HPV ILIKE 'Unaddressed%' THEN 'NE_UNADDR' WHEN ST='NE' THEN 'NE_OTHER' WHEN ST='IA' THEN 'IA' ELSE 'OTHER' END) AS GRP FROM f WHERE REG IS NOT NULL GROUP BY 1)
SELECT g.GRP, e.REPORTING_YEAR, COUNT(DISTINCT g.REG) AS PLANTS, SUM(e.ANNUAL_EMISSION) AS TRI_AIR_LB
FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_AIR_EMISSIONS_POLL_RPT_COMBINED_EMISSIONS e JOIN g ON TO_VARCHAR(e.REGISTRY_ID) = g.REG
WHERE e.PGM_SYS_ACRNM = 'TRIS' GROUP BY 1,2 ORDER BY 1,2;

-- [S21] statement 22
-- [S21] Neighbourhood peer check: ECHO PCT_MINORITY (EPA's figure for people near the site) for active major air facilities in IA, IN, NE: median and quartiles, next to county population from DIM_COUNTY for Muscatine and Daviess
SELECT 'ECHO_MAJOR_AIR' AS SRC, STATE AS ST, COUNT(*) AS N, MEDIAN(PCT_MINORITY) AS MED, PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY PCT_MINORITY) AS P75, PERCENTILE_CONT(0.9) WITHIN GROUP (ORDER BY PCT_MINORITY) AS P90
FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ECHO
WHERE STATE IN ('IA','IN','NE') AND HAS_AIR_PROGRAM AND IS_MAJOR_FACILITY AND IS_ACTIVE AND PCT_MINORITY IS NOT NULL AND POPULATION_DENSITY > 0
GROUP BY 1,2
UNION ALL
SELECT 'DIM_COUNTY', COUNTY_NAME || ', ' || STATE_NAME, POPULATION_2020, NULL, NULL, NULL FROM LIBRARY_MARTS.CORE.DIM_COUNTY WHERE COUNTY_FIPS IN ('19139','18027');

-- [S22] statement 23
-- [S22] Water side for the two GPC plants: quarters by HLRNC code and effluent exceedance counts per year since 2015 (EPA quarterly noncompliance history)
SELECT NPDES_ID, LEFT(YEARQTR,4) AS YR, LISTAGG(COALESCE(NULLIF(TRIM(HLRNC),''),'_'), '') WITHIN GROUP (ORDER BY YEARQTR) AS QTR_CODES, SUM(TRY_TO_NUMBER(NUME90_Q)) AS EFFLUENT_EXCEED, SUM(TRY_TO_NUMBER(NUMCVDT)) AS SCHED_VIOL
FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_NPDES_NPDES_QNCR_HISTORY
WHERE NPDES_ID IN ('IA0003441','IN0059641') AND LEFT(YEARQTR,4) >= '2015'
GROUP BY 1,2 ORDER BY 1,2;
